// Thin, read-only wrapper around the GitHub REST API.
//
// Deliberately GET-only: there is no function anywhere in this file (or in
// mcp-agent.ts, which is the only thing that calls into this file) that
// issues a POST/PATCH/PUT/DELETE to GitHub. That's not a configuration flag
// someone could accidentally flip - it's the entire surface area of the
// code. A model driving this connector cannot make GitHub write a byte,
// regardless of what scopes the underlying token happens to have.
//
// `Env` here is the ambient global interface generated by `wrangler types`
// (OAUTH_KV, MCP_OBJECT) plus GITHUB_PAT/CONNECTOR_PASSWORD merged in via
// env.d.ts - see that file for why those two are separate.
//
// This connector is NOT restricted to an allow-list: it can read any repo the
// GITHUB_PAT has access to. The PAT's own scopes are the access boundary - use
// a fine-grained token limited to the repos/permissions you actually want to
// expose. The check below is a *format* guard, not an access decision.

// GitHub owner and repo names are limited to letters, digits, ".", "-", "_".
// Enforcing that shape is what keeps `repo` from smuggling extra path or query
// segments into the GitHub API URL (the same injection class the path/query
// guards further down defend against). It intentionally does NOT decide which
// repos are reachable - that's the GITHUB_PAT's job.
const REPO_RE = /^[A-Za-z0-9._-]+\/[A-Za-z0-9._-]+$/;

export class InvalidRepoError extends Error {
  constructor(repo: string) {
    super(`Invalid repo "${repo}": expected "owner/name" using only letters, digits, ".", "-", "_".`);
    this.name = "InvalidRepoError";
  }
}

export function assertValidRepo(repo: string): void {
  if (!REPO_RE.test(repo)) {
    throw new InvalidRepoError(repo);
  }
}

async function ghGet(env: Env, path: string): Promise<unknown> {
  const res = await fetch(`https://api.github.com${path}`, {
    headers: {
      Authorization: `Bearer ${env.GITHUB_PAT}`,
      Accept: "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
      "User-Agent": "github-readonly-mcp/1.0 (+schedule-agent)",
    },
  });

  if (!res.ok) {
    const body = await res.text().catch(() => "");
    throw new Error(
      `GitHub API GET ${path} -> HTTP ${res.status} ${res.statusText}${body ? `: ${body.slice(0, 500)}` : ""}`,
    );
  }

  return res.json();
}

export async function listCommits(env: Env, repo: string, branch?: string, limit = 20) {
  assertValidRepo(repo);
  const params = new URLSearchParams({ per_page: String(Math.min(Math.max(limit, 1), 50)) });
  if (branch) params.set("sha", branch);
  const data = (await ghGet(env, `/repos/${repo}/commits?${params}`)) as any[];
  return data.map((c) => ({
    sha: c.sha?.slice(0, 7),
    author: c.commit?.author?.name,
    date: c.commit?.author?.date,
    message: (c.commit?.message || "").split("\n")[0],
    url: c.html_url,
  }));
}

export async function listBranches(env: Env, repo: string) {
  assertValidRepo(repo);
  const data = (await ghGet(env, `/repos/${repo}/branches?per_page=100`)) as any[];
  return data.map((b) => ({ name: b.name, sha: b.commit?.sha?.slice(0, 7), protected: !!b.protected }));
}

export async function listPullRequests(env: Env, repo: string, state: "open" | "closed" | "all" = "open") {
  assertValidRepo(repo);
  const data = (await ghGet(env, `/repos/${repo}/pulls?state=${state}&per_page=30`)) as any[];
  return data.map((p) => ({
    number: p.number,
    title: p.title,
    state: p.state,
    draft: p.draft,
    base: p.base?.ref,
    head: p.head?.ref,
    updated_at: p.updated_at,
    url: p.html_url,
  }));
}

export async function listIssues(env: Env, repo: string, state: "open" | "closed" | "all" = "open") {
  assertValidRepo(repo);
  const data = (await ghGet(env, `/repos/${repo}/issues?state=${state}&per_page=30`)) as any[];
  // GitHub's /issues endpoint also returns PRs; filter those out so this tool is issues-only.
  return data
    .filter((i) => !i.pull_request)
    .map((i) => ({
      number: i.number,
      title: i.title,
      state: i.state,
      labels: (i.labels || []).map((l: any) => (typeof l === "string" ? l : l.name)),
      updated_at: i.updated_at,
      url: i.html_url,
    }));
}

// Splits `path` on "/" and rejects anything that could let the request
// escape the `repo` segment of the GitHub contents URL: leading/interior
// empty segments (a leading "/" or "//") and "." / ".." segments (which
// `fetch`/`URL` would normalize, letting a path like
// "../../../../repos/other-org/private-repo/contents/.env" reach a repo
// whose "owner/name" was never validated). Each surviving segment is
// then encodeURIComponent-ed individually so characters like "/" or "?"
// can't be smuggled back in through the segment itself, and rejoined with
// literal "/" separators.
//
// An empty path is the repo root ("/repos/{repo}/contents/" lists it), and a
// single trailing slash on a directory path (e.g. "src/") is tolerated -- both
// are legitimate directory-listing inputs the get_file_contents tool advertises,
// so we normalize them away rather than reject them.
function safeContentsPath(path: string): string {
  const normalized = path.endsWith("/") ? path.slice(0, -1) : path;
  if (normalized === "") return "";
  const segments = normalized.split("/");
  for (const segment of segments) {
    if (segment === "" || segment === "." || segment === "..") {
      throw new Error(
        `Invalid path "${path}": path segments must not be empty, ".", or ".." (no traversal or absolute paths allowed).`,
      );
    }
  }
  return segments.map((segment) => encodeURIComponent(segment)).join("/");
}

// GitHub returns file content as base64 of the raw UTF-8 bytes. atob() alone
// yields a "binary string" (one char per byte), which garbles any non-ASCII
// text such as Bengali. Convert the bytes back and decode them as UTF-8.
function base64ToUtf8(b64: string): string {
  const binary = atob(b64.replace(/\n/g, ""));
  const bytes = Uint8Array.from(binary, (c) => c.charCodeAt(0));
  return new TextDecoder("utf-8").decode(bytes);
}

export async function getFileContents(env: Env, repo: string, path: string, ref?: string) {
  assertValidRepo(repo);
  const safePath = safeContentsPath(path);
  const params = ref ? `?ref=${encodeURIComponent(ref)}` : "";
  const data = (await ghGet(env, `/repos/${repo}/contents/${safePath}${params}`)) as any;
  if (Array.isArray(data)) {
    // path was a directory
    return { type: "dir", entries: data.map((e: any) => ({ name: e.name, type: e.type, path: e.path })) };
  }
  if (data.encoding === "base64" && typeof data.content === "string") {
    const decoded = base64ToUtf8(data.content);
    return { type: "file", path: data.path, size: data.size, content: decoded };
  }
  return { type: "file", path: data.path, size: data.size, content: null, note: "Non-text or unsupported encoding" };
}

// GitHub's code search combines multiple `repo:`/`org:`/`user:` qualifiers
// with OR, not AND. Since we append our own `repo:${repo}` qualifier to
// scope the search to the requested repo, a caller-supplied query containing
// one of these qualifiers (e.g. "repo:other-org/private-repo") doesn't
// override ours -- it adds a second, unauthorized scope that GitHub unions
// results from. Reject any query that tries to set its own scope qualifier
// so the appended `repo:${repo}` remains the only one in effect. The leading
// character class covers every delimiter GitHub may tokenize a qualifier
// after -- whitespace, "(", and quotes -- so e.g. `foo"repo:bar` is caught too.
const SCOPE_QUALIFIER_RE = /(?:^|[\s("'])-?(?:repo|org|user):/i;

function assertNoScopeQualifier(query: string): void {
  if (SCOPE_QUALIFIER_RE.test(query)) {
    throw new Error(
      `Search query must not contain "repo:", "org:", or "user:" qualifiers -- this connector already scopes searches to the requested repo.`,
    );
  }
}

export async function searchCode(env: Env, repo: string, query: string) {
  assertValidRepo(repo);
  assertNoScopeQualifier(query);
  const q = encodeURIComponent(`${query} repo:${repo}`);
  const data = (await ghGet(env, `/search/code?q=${q}&per_page=20`)) as any;
  return (data.items || []).map((it: any) => ({ path: it.path, url: it.html_url }));
}

// Lists the repos the GITHUB_PAT can reach, most-recently-pushed first, so a
// caller can discover what's in scope without a hard-coded allow-list. This is
// still read-only (GET /user/repos) and still bounded by the token: it returns
// exactly the repos the PAT is allowed to see, nothing more.
export async function listRepos(env: Env, limit = 30) {
  const perPage = Math.min(Math.max(limit, 1), 100);
  const params = new URLSearchParams({
    per_page: String(perPage),
    sort: "pushed",
    affiliation: "owner,collaborator,organization_member",
  });
  const data = (await ghGet(env, `/user/repos?${params}`)) as any[];
  return data.map((r) => ({
    full_name: r.full_name,
    private: !!r.private,
    default_branch: r.default_branch,
    pushed_at: r.pushed_at,
    url: r.html_url,
  }));
}
